package com.aistock.market.alert;
import static com.aistock.market.alert.AlertEvidenceRecords.*;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.ObjectMapper;
import java.sql.Timestamp;import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;
final class AlertEvidenceStore {
 private final JdbcTemplate jdbc;private final Clock clock;private final ObjectMapper mapper;private final TransactionTemplate tx;
 AlertEvidenceStore(JdbcTemplate jdbc,Clock clock,ObjectMapper mapper){this.jdbc=jdbc;this.clock=clock;this.mapper=mapper;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);}
 Receipt begin(Request r,String hash){return tx.execute(s->{int added=jdbc.update("insert ignore into alert_evidence_operation(operation_id,request_hash,state,lease_until,created_at) values(?,?,'RUNNING',?,?)",r.operationId().toString(),hash,Timestamp.from(r.leaseUntil()),Timestamp.from(clock.instant()));var row=lock(r.operationId());if(!hash.equals(row.get("request_hash")))throw error("ALERT_EVIDENCE_OPERATION_CONFLICT",HttpStatus.CONFLICT);if(added==1)return null;return expireOrRead(r.operationId(),row);});}
 Receipt operation(UUID id){return tx.execute(s->expireOrRead(id,lock(id)));}
 Receipt finish(UUID id,String state,String code){return tx.execute(s->{var row=lock(id);if(!"RUNNING".equals(row.get("state")))return receipt(id,row);var current=expireOrRead(id,row);if(!"RUNNING".equals(current.state()))return current;jdbc.update("update alert_evidence_operation set state=?,fencing_revision=fencing_revision+1,error_code=?,finished_at=? where operation_id=?",state,code,Timestamp.from(clock.instant()),id.toString());return new Receipt(id,state,null,code);});}
 Receipt publish(Request request,Evidence evidence){return com.aistock.market.marketlifecycle.MarketEvidenceGate.local(()->{com.aistock.market.marketlifecycle.MarketEvidenceGate.raw(evidence.rawVersionId().toString());return tx.execute(s->{var row=lock(request.operationId());var current=expireOrRead(request.operationId(),row);if(!"RUNNING".equals(current.state()))return current;
  com.aistock.market.marketlifecycle.MarketEvidenceGate.publishable(jdbc,evidence.rawVersionId().toString());jdbc.update("insert into alert_evidence_version(evidence_id,instrument_id,raw_version_id,trade_date,content_hash,evidence_json,created_at) values(?,?,?,?,?,?,?)",evidence.id().toString(),evidence.instrumentId(),evidence.rawVersionId().toString(),evidence.tradeDate(),evidence.contentHash(),json(evidence),Timestamp.from(clock.instant()));
  if(!clock.instant().isBefore(request.leaseUntil()))throw error("ATTEMPT_EXPIRED",HttpStatus.CONFLICT);
  jdbc.update("update alert_evidence_operation set state='AVAILABLE',fencing_revision=fencing_revision+1,evidence_id=?,finished_at=? where operation_id=?",evidence.id().toString(),Timestamp.from(clock.instant()),request.operationId().toString());return new Receipt(request.operationId(),"AVAILABLE",evidence.id(),null);
 });});}
 Evidence version(UUID id){return com.aistock.market.marketlifecycle.MarketEvidenceGate.local(()->{var rows=jdbc.queryForList("select evidence_json from alert_evidence_version where evidence_id=?",String.class,id.toString());if(rows.isEmpty())throw error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);try{var result=mapper.readValue(rows.get(0),Evidence.class);com.aistock.market.marketlifecycle.MarketEvidenceGate.raw(result.rawVersionId().toString());return result;}catch(com.aistock.common.BusinessException e){throw e;}catch(Exception e){throw error("ALERT_EVIDENCE_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}});}
 String requestHash(Request request){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(request)));}catch(Exception e){throw AlertLocalUseOwner.unavailable();}}
 String marketUseInput(Request request){return tx.execute(s->{var row=lock(request.operationId());if(!requestHash(request).equals(row.get("request_hash"))||!"RUNNING".equals(row.get("state"))||!clock.instant().isBefore(((Timestamp)row.get("lease_until")).toInstant()))throw AlertLocalUseOwner.unavailable();return request.rawVersionId().toString();});}
 com.aistock.market.marketlifecycle.MarketLifecycleRecords.TerminalProof executionTerminal(Request request,List<String> versions){return tx.execute(s->{var row=lock(request.operationId());if(!requestHash(request).equals(row.get("request_hash"))||!versions.equals(List.of(request.rawVersionId().toString())))throw AlertLocalUseOwner.unavailable();var terminal=expireOrRead(request.operationId(),row);row=lock(request.operationId());if(!Set.of("AVAILABLE","FAILED","SKIPPED_STALE").contains(terminal.state())||row.get("finished_at")==null)throw AlertLocalUseOwner.unavailable();return new com.aistock.market.marketlifecycle.MarketLifecycleRecords.TerminalProof(new com.aistock.common.marketlifecycle.MarketUseRecords.UseIdentity("market","ALERT_EVIDENCE_PUBLISH",request.operationId().toString(),"1"),"FAILED".equals(terminal.state())?"FAILED":"SUCCEEDED",((Timestamp)row.get("finished_at")).toInstant(),row.get("fencing_revision").toString(),terminal.evidenceId()==null?request.operationId().toString():terminal.evidenceId().toString(),versions);});}
 private Map<String,Object> lock(UUID id){var rows=jdbc.queryForList("select * from alert_evidence_operation where operation_id=? for update",id.toString());if(rows.isEmpty())throw error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);return rows.get(0);}
 private Receipt expireOrRead(UUID id,Map<String,Object> row){if("RUNNING".equals(row.get("state"))&&!clock.instant().isBefore(((Timestamp)row.get("lease_until")).toInstant())){jdbc.update("update alert_evidence_operation set state='FAILED',fencing_revision=fencing_revision+1,error_code='ATTEMPT_EXPIRED',finished_at=? where operation_id=?",Timestamp.from(clock.instant()),id.toString());return new Receipt(id,"FAILED",null,"ATTEMPT_EXPIRED");}return receipt(id,row);}
 private Receipt receipt(UUID id,Map<String,Object> row){return new Receipt(id,(String)row.get("state"),row.get("evidence_id")==null?null:UUID.fromString((String)row.get("evidence_id")),(String)row.get("error_code"));}
 private String json(Evidence evidence){try{return mapper.writeValueAsString(evidence);}catch(Exception e){throw error("ALERT_EVIDENCE_RECORD_INVALID",HttpStatus.INTERNAL_SERVER_ERROR);}}
 static BusinessException error(String code,HttpStatus status){return new BusinessException(code,"预警证据暂未完成，已有记录保留",status);}
}
